create function public.armador_commit_state(expected_revision bigint, document jsonb, expected_owner uuid) returns bigint language plpgsql security invoker set search_path='' as $$ begin if expected_owner is null or expected_owner is distinct from auth.uid() then raise exception 'Account changed. Sign in again.' using errcode='42501'; end if; return public.armador_save_state(expected_revision,document); end $$; revoke all on function public.armador_commit_state(bigint,jsonb,uuid) from public,anon; grant execute on function public.armador_commit_state(bigint,jsonb,uuid) to authenticated;
